            ["界面屏数", "6 屏", "5 屏（开局 + 四页签 + 结局）", "不再新增页签"],
            ["荣誉种类", "4 种", "写进 P3 数值表，代码未接", "不新增"],
            ["音频", "0", "0", "本期不做"],
            ["位图素材", "0 张", "0（纯色块 + 文字）", "不引入，包体积优先"],
